CREATE TABLE `bank_card` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bank_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `card_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '卡片名称',
  `card_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '信用卡，金卡、白金卡、钻石卡',
  `card_class` int DEFAULT NULL COMMENT '借记卡等级，一类卡、二类卡',
  `card_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `card_organization` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNIONPAY',
  `cover` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图片',
  `region_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `card_last_four` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `credit_limit` double DEFAULT NULL,
  `annual_fee_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rigid_fee_amount` double DEFAULT NULL,
  `waiver_method` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `waiver_value` double DEFAULT NULL,
  `fee_month` int DEFAULT NULL,
  `fee_day` int DEFAULT NULL,
  `statement_day` int DEFAULT NULL,
  `repayment_rule_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `repayment_day` int DEFAULT NULL,
  `repayment_offset_days` int DEFAULT NULL,
  `max_interest_free_days` int DEFAULT NULL,
  `available_limit` double DEFAULT NULL,
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY',
  `expiry` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'YYYYMM',
  `created_at` bigint NOT NULL,
  `updated_at` bigint DEFAULT NULL,
  `template_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_8f2b7ce439989da5dba4c6cc9de` (`bank_id`),
  KEY `fk_template_id` (`template_id`),
  CONSTRAINT `fk_template_id` FOREIGN KEY (`template_id`) REFERENCES `bank_card_template` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
