DROP TABLE IF EXISTS `bank_sms_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bank_sms_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `bank_id` varchar(50) NOT NULL COMMENT 'bank.id（字符串）',
  `bank_name` varchar(100) NOT NULL COMMENT '银行名称',
  `sms_numbers_csv` varchar(500) NOT NULL COMMENT '短信号码，逗号分隔',
  `sms_template` text NOT NULL COMMENT '标准短信模板',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` bigint NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_bank_sms_rule_bank_id` (`bank_id`),
  KEY `idx_bank_sms_rule_enabled` (`is_enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

