--
-- Table structure for table `task`
--

DROP TABLE IF EXISTS `task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `date` bigint DEFAULT NULL,
  `repeat_type` enum('ONE_TIME','DAILY','WEEKLY','MONTHLY','YEARLY') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ONE_TIME',
  `reminder_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `high_priority` tinyint NOT NULL DEFAULT '0',
  `advance_reminder_minutes` smallint DEFAULT NULL,
  `status` enum('PENDING','EXPIRED','COMPLETED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `region_type` enum('NATIONWIDE','REGIONAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NATIONWIDE',
  `region_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地区限制（对应 region.region_code；NATIONWIDE 时为 NULL）',
  `region_province_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region_city_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行ID',
  `bank_card_id` int DEFAULT NULL COMMENT '银行卡ID',
  `bank_card_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '卡类型',
  `bank_card_level` int DEFAULT NULL COMMENT '卡等级',
  `bank_card_organization` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `task_template_id` int DEFAULT NULL COMMENT '关联 task_template.id',
  `benefit_category_id` int DEFAULT NULL COMMENT '优惠类目 ID（benefit_category.id）',
  `benefit_amount` decimal(10,2) DEFAULT NULL,
  `benefit_voucher_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `benefit_platform_id` int DEFAULT NULL COMMENT '关联优惠平台ID (benefit_platform.id)',
  `frequency_control` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` bigint NOT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务表，与 task_create_examples.md 对齐';
/*!40101 SET character_set_client = @saved_cs_client */;

